  updated_at = now();

-- 17 · KIEJ (Manik), se pronuncia Kiäch
insert into nahual_long_texts
  (nahual_index, lang, heading, directions, body, ceremonies, body_level, power_animal)
values (
  17, 'es',
  'KIEJ (Manik), se pronuncia Kiäch',
  'E KAWOQ, O TZ’IKIN, S IMOX, N AAJ',
  array[
    'KIEJ es la interacción de los campos de fuerza de los cuatro puntos cardinales y los cuatro elementos, el ritmo dinámico de la vida; KIEJ es el espíritu de las colinas, montañas, ríos, lagos y paisajes que actúa sobre nuestro ser humano, el campo de fuerza de los animales de poder indígenas y celtas que actúa sobre el ser humano.',
    'KIEJ es el ciervo que se sostiene sobre cuatro patas, en el símbolo del instinto y la intuición, las energías de las fuerzas naturales que nos fortalecen físicamente, la fuerza electromagnética de nuestro planeta, la intensidad de la fuerza de realización humana, la gravedad que ancla al ser humano, la expansión y contracción de la fuerza en el símbolo del pulso del corazón, la acción y la reacción subsiguiente, el cazador y el animal cazado, que simbólicamente representan la vida y la muerte.',
    'El Nahual KIEJ está especialmente conectado con el campo de fuerza de los cuatro puntos cardinales, que están en armonía entre sí. Son los cuatro pilares sobre los que descansa nuestra existencia, pero también nuestro planeta. El venado, como animal de poder de este Nahual, se sostiene con sus cuatro patas en los cuatro puntos cardinales. Es ágil, vigoroso, intuitivo (instintivo) y vigilante. A partir de estas cualidades sobrevive y conserva su libertad.',
    'También los cuatro elementos —fuego, tierra, aire y agua— deberían estar siempre en equilibrio entre sí. Esta armonía también debería mantenerla el ser humano en sí mismo. Vibra en esta armonía en el ritmo de la vida. Los cuatro elementos se muestran en el ser humano como cuerpo, espíritu, sentimiento y voluntad. Se unen en el corazón que todo lo conecta, ama y clarifica.',
    'Así, el ser humano está también en el centro de la Cruz MAYA, que es guardada por el Nahual KIEJ. La sanación del ser humano se produce siempre en la armonización de los pensamientos (aire), las emociones (agua), la voluntad (fuego) y la corporalidad (tierra), en los cuales los elementos se manifiestan en la conciencia humana.',
    'KIEJ es el Nahual desde cuya fuerza nos mantenemos en constante movimiento. Siempre que el ser humano se encuentre en desequilibrio, tiene la posibilidad de reconocer la dominancia de uno o varios elementos en sí mismo y armonizarlos entre sí. De ahí surge el ser humano interiormente libre, que desde esta investidura se convierte en Señor de la vida y de la muerte.',
    'La conexión con los cuatro elementos significa que, en sintonía con los guardianes de los elementos, verdaderamente podemos mover montañas. Por esta razón, KIEJ es una de las fuerzas físicamente más eficaces del calendario sagrado MAYA. Nos recuerda volver a ser conscientes de las fuentes de fuerza de los reinos naturales y emplear a los seres de los reinos naturales para la configuración de nuestra vida, para la sanación de nuestro planeta, con respeto y conforme a sus tareas.',
    'En esta conexión, nuestra Madre Tierra vuelve a ser sacralizada; el reino humano y los reinos naturales volverán así a integrarse entre sí y a darse mutuamente fuerza y dinamismo para una vida sanadora.',
    'Las personas nacidas en el signo KIEJ son ágiles, fuertes, responsables, inteligentes y están en equilibrio interior consigo mismas. Pero están sobre todo en equilibrio exterior con los seres y elementos de la naturaleza. Por su firmeza y dinamismo asumen responsabilidad, están a menudo en puestos de liderazgo, aman el reconocimiento y los cargos públicos. Poseen un espíritu abierto, son de amplia visión, mentalmente ágiles e intuitivas. La persona nacida en KIEJ está también fuertemente llamada a mantenerse consciente de estas fuentes de fuerza y a nutrirlas y cuidarlas con conocimiento y en equilibrio. Así, las personas nacidas en KIEJ son buenas psicólogas, jueces y abogadas, y especialmente aptas para profesiones sociales.',
    'Las debilidades de la persona nacida en KIEJ son su reserva. No ser consciente de sus raíces significa para la persona nacida en KIEJ que estas mismas fuerzas se dirigen en forma de agresiones, odio y separación contra ella misma. Por esta razón tienden a ver solo el propio beneficio y a reaccionar ante otros con control y poder. Su desequilibrio interior se muestra entonces en orgullo exagerado, en soberbia y en un fuerte desequilibrio de la vida emocional. El aspecto corporal suele estar dominante frente a todas las demás cualidades humanas; un culto corporal exagerado, una sexualidad orientada únicamente a la satisfacción del placer, son consecuencias de este unilateralismo centrado en el cuerpo.',
    'Una conexión demasiado fuerte con las fuerzas de la naturaleza crea en estas personas una fuerza tosca y sin pulir, bajo la cual sufren las personas de su entorno.'
  ],
  array[
    'Pedimos en el día KIEJ la investidura desde los reinos naturales, el fortalecimiento de la fuerza física y orientada a la vida física, a la profesión. Pedimos conocimiento, reconocimiento en el lugar de trabajo, autenticidad y seguridad, la realización de nuestra tarea de vida.',
    'En KIEJ pedimos el equilibrio de los cuatro elementos en nosotros. Pedimos la liberación de influencias negativas de terceras personas, la liberación del orgullo y la soberbia. Pedimos bienestar, fuerza en las manos y las piernas, alegría en el trabajo, fuerza sanadora para nuestras manos.',
    'En el día KIEJ también podemos pedir por la felicidad en la vida, si estamos dispuestos a crear para ello la base en nosotros mismos. Esta base se conforma desde un amor que se despliega hacia la naturaleza y hacia nuestros semejantes, desde el amor a DIOS y a sus ayudantes. Pedimos en KIEJ fuerza y armonía en todos los ámbitos de la vida, y el equilibrio y la paz con el mundo físico y material.'
  ],
  'Brazos y piernas, manos y pies',
  'Ciervo, caballo, animales de poder indígenas y celtas'
)
on conflict (nahual_index, lang) do update set
