  directions = excluded.directions,
  body = excluded.body,
  ceremonies = excluded.ceremonies,
  body_level = excluded.body_level,
  power_animal = excluded.power_animal,
  updated_at = now();

-- 18 · Q’ANIL (Lamat), se pronuncia Kanil
insert into nahual_long_texts
  (nahual_index, lang, heading, directions, body, ceremonies, body_level, power_animal)
values (
  18, 'es',
  'Q’ANIL (Lamat), se pronuncia Kanil',
  'E AJPUU, O AJMAQ, S IQ, N I’X',
  array[
    'Q’ANIL es la fuerza de la unión de la semilla y el óvulo, la fecundación y la fertilidad, la fuerza creadora de Dios en la sexualidad, la realización y puesta en práctica de ideas, proyectos y visiones que resultan de esta fuerza cósmica, la vida que se despliega de nuevo desde el plan de la creación, la fertilidad planetaria que se manifiesta desde los siete rayos creadores de Dios, la creación sutil de formas y seres, plenitud y crecimiento espiritual y material, los seres de otros mundos que se conectan con el plan de la creación, nuevas formas de interacción y convivencia del ser humano orientado cósmicamente, el programa de la NUEVA TIERRA Y EL NUEVO SER HUMANO que se abre en el corazón de Q’ANIL.',
    'El Nahual Q’ANIL activa la fuerza creadora interior y exterior del ser humano. Así, este Nahual contiene el programa de vida del ser humano en sintonía con el crecimiento en los reinos naturales. Q’ANIL está en constante conexión con las divinidades del plan de la creación de Dios. Es la ley cósmica del amor, desde cuyo campo de fuerza se unen la semilla y el óvulo, para crear nueva vida y otros estados del ser en los mundos del más allá.',
    'Así, Q’ANIL está, en la cultura MAYA, en el ámbito de influencia y campo de fuerza de la belleza y plenitud que otorga Venus. Creamos con nuestros pensamientos, sentimientos y a través de nuestro actuar nuestra propia realidad.',
    'Q’ANIL es la semilla depositada en nosotros que, en conexión con lo femenino, fecunda nuestras ideas y representaciones. Q’ANIL representa la plenitud y la diversidad de formas de la creación, y la riqueza dispuesta en el ser humano. Igual que la belleza y diversidad de nuestro planeta Tierra, también le es posible al ser humano desplegar en sí mismo la imagen del planeta y manifestar también hacia fuera la belleza y la plenitud.',
    'Q’ANIL yace como semilla de crecimiento del ser humano en el elemento tierra fértil. Este necesita para el crecimiento el fuego solar del Este, que da luz y calor; el agua del Sur, que trae plenitud y sanación; y el aire puro y claro del Norte. Así prospera también nuestra personalidad desde las mismas cualidades: nuestra fuerza interior y belleza surgen de la pureza de los sentimientos y los pensamientos, y necesitan del fuego humano que da calor y luz. Todas estas cualidades se muestran en el ser humano como felicidad, alegría, plenitud, esplendor y belleza. Q’ANIL es la germinación de esta semilla, la plenitud que se abre en el amor de nuestra existencia terrenal.',
    'Así, en el día Q’ANIL son especialmente eficaces las fuerzas de los cuatro puntos cardinales y los siete rayos creadores de Dios. En su fuerza sanamos también la infertilidad humana y los problemas en la sexualidad.',
    'Un día Q’ANIL es el momento ideal para crear vida, visiones, proyectos. También la fertilidad y fuerza de un suelo agotado puede recuperarse con Q’ANIL a través del alimento sutil.',
    'Las personas nacidas en el día Q’ANIL son muy intuitivas; actúan de forma estimulante y motivadora en sus ideas y representaciones. Tienen dones especiales para crear materia y llenarla de contenidos espirituales. Son responsables y colaboradoras apreciadas y realizadoras de ideas.',
    'Las personas nacidas en Q’ANIL dan la impresión de timidez, pero se nutren, de forma oculta, de una gran fuerza interior; son buenas amantes con empatía y fuerza. Aprovechan su profunda conexión con la energía sexual y creadora para un entorno vital creativo y vital, y por ello son también buenas empresarias, artistas especiales y músicas. En el ámbito de la sanación saben poner su fuerza y dinamismo al servicio de las fuerzas creadoras divinas.',
    'Las debilidades de las personas nacidas en Q’ANIL son la credulidad, la labilidad y la falta de fiabilidad. Cuando no son conscientes de su fuerza, crean desde pensamientos y sentimientos impuros un caos de vida, sin reconocerse a sí mismas como causantes de este caos. Conectadas con su estimulante fuerza sexual, son gustosamente también víctimas de sus propias pasiones y caen fácilmente en la dependencia de otros. El abuso de su fuerza creadora desviada las enreda gustosamente en empresas que surgen del egoísmo, de la soberbia, de la altivez y de un ansia de poder exagerada, que luego se desmoronan pronto de nuevo.'
  ],
  array[
    'En el día Q’ANIL pedimos la fertilidad para los seres humanos, para los animales, para la tierra, para nuestras visiones y proyectos. Pedimos por un crecimiento sano de las plantas, por energía para nuestros alimentos, por la bendición nutricia en la agricultura, por una cosecha abundante.',
    'Pedimos el éxito de una idea, una visión, un proyecto, el éxito de nuestras tareas en la vida, por el éxito en nuestro mundo laboral. Pedimos a Q’ANIL un buen nuevo comienzo después de un despido, un cambio de profesión, un declive personal y un cambio. Pedimos el sano crecimiento de nuestros hijos y la fuerza y constancia para las visiones de vida de los jóvenes.',
    'En el día Q’ANIL pedimos, en el ámbito de la sanación, la liberación y sanación de la impotencia y la frigidez, la sanación de las partes del alma con ello conectadas desde vidas anteriores. Pedimos la sanación y redención de personas que han sufrido abuso sexual.',
    'Pedimos (en conexión con el Nahual AAJ), en la agricultura, la liberación de plagas en el suelo cultivado, la liberación de enfermedades de animales y plantas, y la salud nutricia del suelo.'
  ],
  'Ovarios, útero, esperma masculino, órganos sexuales',
  'Conejo, liebre'
)
on conflict (nahual_index, lang) do update set
