-- 19 · TOOJ (Muluc), se pronuncia Toch
insert into nahual_long_texts
  (nahual_index, lang, heading, directions, body, ceremonies, body_level, power_animal)
values (
  19, 'es',
  'TOOJ (Muluc), se pronuncia Toch',
  'E IMOX, O NOJ, S A’KAB’AL, N TZ’IKIN',
  array[
    'TOOJ es el equilibrio en la rueda de la vida, el don y la entrega, la gracia divina que fluye hacia mí, lo generoso en el perdón, el equilibrio entre dar y recibir, la ofrenda en el principio de la disposición a dar. TOOJ es también el don en los ritos, el TOOJ de una ceremonia MAYA, la ofrenda y el regalo por aquello que pedimos en el ciclo desde las fuentes espirituales. TOOJ es la corriente de vida que, desde el principio de dar, mantiene todo en movimiento y flujo. TOOJ es la fuerza sagrada de la piedra del corazón, el jade, la piedra de la vida y de la sabiduría de los MAYA.',
    'TOOJ es el Nahual que cierra el ciclo de dar y recibir. Todo lo que pedimos al mundo espiritual está también relacionado con lo que estamos dispuestos a dar. TOOJ es la fuerza del amor en el dar. A través de nuestra disposición a dar se abren las puertas para lo que puede sernos concedido. Cuando acumulamos materia y saber, esto sucede a menudo a costa de otros. Por ello, lo que nos hemos creado se vuelve también contra nosotros y contra nuestro flujo de vida. Quien llega a la plenitud de la vida por estar dispuesto a dar, crea en sí un magnetismo que le permite también recibir la plenitud correspondiente.',
    'El sacerdote MAYA entrega, en las ceremonias de fuego, el sagrado TOOJ en forma de una gran plenitud de valiosos materiales ceremoniales. Con ello, el chamán paga, en el sentido más literal de la palabra, por lo que la persona afectada y necesitada de sanación ha manifestado por desconocimiento. Así, TOOJ representa el símbolo del equilibrio, del llenado de un vacío interior que se creó por avaricia o por una conciencia de pobreza limitante como bloqueo. En TOOJ equilibramos culpa e imperfección a través de lo que estamos dispuestos a dar.',
    'Podría denominarse a TOOJ también el guardián del karma abierto que exige equilibrio. Este dar significa, en nuestro círculo cultural, la disposición a donar para un proyecto social, a ponerse al servicio de un proyecto social mediante trabajo, y cosas semejantes. Conflictos y disputas en la comunidad también pueden equilibrarse mediante un TOOJ, en la forma de que la persona ávida de poder busca, dispuesta al consenso, una solución conjunta. TOOJ representa también este consenso y mantiene así también unida a la comunidad. Puede compararse con una energía rotatoria que nos mantiene en constante movimiento e invita al dar.',
    'Desde el don y la entrega se da también, en la rueda de la vida, la base para una vida que se despliega espiritualmente. A través de nuestra atención y vigilancia mantenemos, en el dar, el contacto con los planos invisibles, que nos abren, en gratitud, el camino hacia la realización y la plenitud. En el cristianismo, TOOJ es la fuerza de la ofrenda, del ayuno, de la disposición a donar y a ocuparse de otras personas.',
    'TOOJ representa, en su lado oscuro, los efectos de nuestras emociones y pensamientos inferiores como consecuencia de nuestra actitud. Nos arrastra hacia la enfermedad, el dolor, el sufrimiento y la carga de culpa, cuando no somos conscientes de su naturaleza generosa y solo somos tomadores y explotadores. Por ello, TOOJ es también un día del mago negro, que en este día configura sus rituales y ofrece sus dones del lado oscuro y destructivo de TOOJ, vinculando así fuerzas para sus intenciones destructivas.',
    'Las personas nacidas en el día TOOJ son, en sus cualidades básicas, serenas, flemáticas, respetuosas, llenas de alegría de vivir, orientadas a la comunidad, con la necesidad de destacarse de los demás mediante especial atención y regalos. Actúan en la comunidad de forma equilibradora y armonizadora, y por ello son también muy apreciadas. Las personas nacidas en TOOJ son muy sensitivas y emocionales, lo cual también puede resultarles perjudicial si no lo manejan con conciencia. Su disposición a dar es señal de que están dispuestas a soltar la materia y a crear espacio para lo nuevo.',
    'Las debilidades de las personas nacidas en TOOJ son un carácter lábil e inquieto; en sus acciones son, por su unilateralismo y su actitud de tomadoras, cortas de miras, destructivas, centradas únicamente en el propio beneficio. Están predispuestas materialistamente y son propensas a accidentes. Tienen la tendencia a asumir la culpa de otros, a sufrir con ellos o a provocar compasión, y a languidecer en autocompasión.',
    'Las personas nacidas en TOOJ tienen a menudo, en su disposición anímica, la tarea de equilibrar algo por sus ancestros o también por su propia actitud de vida anterior. Esto las lleva a menudo a situaciones de vida intensas y hace que vuelvan a perder lo trabajado una y otra vez. Su actitud de dar y regalar está, desde las partes oscuras de TOOJ, conectada con una intención. Regalan para llamar la atención, para forzar un cambio de comportamiento en el otro, para parecer generosas, entre otras razones.'
  ],
  array[
    'En el día TOOJ pedimos, mediante la gratitud y la ofrenda, el equilibrio en el dar y el recibir. Pedimos perdón por lo que provocamos en otros mediante nuestro pensar, sentir y actuar. Esto se refiere también al robo espiritual, energético o material, a tomar energías sin preguntar, a aprovecharse de la hospitalidad, a irrumpir en ámbitos íntimos de otra persona, al acoplamiento medial no solicitado a otro ser humano.',
    'Así, a través de nuestra ofrenda, a través del ritual del perdón, a través de una entrega consciente hacia el dar interpersonal, pedimos la liberación de cargas obstaculizantes y de fuerzas bloqueadoras activadas por nosotros mismos. Con el don equilibramos el desequilibrio interior y exterior. Estabilizamos nuestra existencia y pedimos al Creador divino conocimiento y la actitud interior de no esperar, sino de dar confiando en el ciclo divino.',
    'En el ritual del dar y el perdonar podemos también apartar peligros de todo tipo que nosotros mismos hemos provocado por falta de conocimiento y por la actitud básica de tomar sin preguntar (accidentes, sufrimiento, miedo y muerte prematura, catástrofes, venganza, magia negra, etc.).'
  ],
  'Manos, corazón',
  'La entrega de los animales domésticos, el amor incondicional del perro'
)
on conflict (nahual_index, lang) do update set
  heading = excluded.heading,
  directions = excluded.directions,
  body = excluded.body,
  ceremonies = excluded.ceremonies,
  body_level = excluded.body_level,
  power_animal = excluded.power_animal,
  updated_at = now();

-- 20 · TZ’I (Oc), se pronuncia Tsi
insert into nahual_long_texts
  (nahual_index, lang, heading, directions, body, ceremonies, body_level, power_animal)
values (
  20, 'es',
  'TZ’I (Oc), se pronuncia Tsi',
  'E IQ, O TIJAAX, S KAT, N AJMAQ',
  array[
    'TZ’I representa el orden espiritual y físico, la protección frente a influencias destructivas que de ello resulta, la ley cósmica del amor que todo lo une, la autoridad espiritual y humana, el sentido de la justicia, el orden en el despliegue gradual del alma, la fidelidad espiritual, la palabra que se eleva desde el corazón y la experiencia de vida, la jerarquía en los diferentes planos del ser y mundos, los guardianes del orden social y de la legislación humana, los guardianes del orden cósmico-espiritual, la fuerza de la fe y de la confianza.',
    'TZ’I, el guardián espiritual del orden cósmico y de la verdad, lleva en sí la ley cósmica de la cual se sostienen unidos entre sí los diferentes planos del ser, los diversos espacios espirituales de vida de los mundos inferior, medio y superior. En el pueblo hebreo, este orden fue especialmente reconocido, guardado y considerado un misterio. Desde el tesoro de sabiduría de los grandes sabios y maestros de este pueblo se construye, en conexión con las divinidades de las fuerzas creadoras, el nuevo orden mundial. El sentido de justicia de las personas conectadas con el corazón es la más alta expresión de este orden espiritual en el ser humano.',
    'En la impartición de justicia debería el ser humano ser consciente de que la condena de una persona da protección a la comunidad frente a individuos que viven fuera del orden. A la vez debería reconocerse que estas personas también se encuentran fuera del orden cósmico. Por el desorden dado en el alma, están bajo la influencia de fuerzas separadoras y funestas. La sanación de estas personas se produce mediante la ayuda en el reordenamiento, la sanación y la purificación del alma del ser humano. TZ’I nos da en esto, una y otra vez, la orientación para vivir, expresar e integrar en la impartición de justicia, mediante el conocimiento y en el principio del amor cósmico, la legalidad divina.',
    'Así como los pueblos antiguos y los sabios de las culturas mantenían, a través de la orientación hacia las leyes cósmicas, la reconexión con lo divino, así deberíamos también ser conscientes de que toda forma de transgresión de las leyes representa un alejamiento de lo divino. La reintegración en el orden divino está conectada con la fuerza del amor y de la gracia divina. TZ’I nos protege de que, desde la ley de la vida, desde el campo de fuerza de la comunidad protectora y de las fuerzas que nos acompañan y protegen del cosmos divino, caigamos unilateralmente en el mundo estrecho e ilusorio de la materia.',
    'A través de TZ’I reconocemos las partes del alma desde las cuales estamos desviados, que nos guían hacia experiencias de vida en las que también en el entorno del ser humano surge separación, la cual existe igualmente en el alma del ser humano. En TZ’I, los magos oscuros aprovechan las cualidades negativas del ser humano, reforzando mediante influencia mágica el desorden interior (caos, odio, envidia, celos...).',
    'TZ’I es el Nahual de la confianza en la guía divina y la protección divina. Nuestros acompañantes espirituales nos asisten, desde diferentes planos del ser, con su fuerza y sabiduría, en nuestra búsqueda de la verdad. Símbolo de este orden en el despliegue del alma, del orden espiritual y de las leyes cósmicas es la construcción escalonada de una pirámide. Paso a paso caminamos por el camino de la investidura. Escalón a escalón (entre los MAYA, en ascenso serpentino) recorremos los mundos de vida y experiencia de diferentes dimensiones y espacios cósmicos. Cada escalón lleva en sí el acceso a mundos, a experiencias de vida, a partes del alma y a fuerzas espirituales que habitan estos espacios espirituales, que nos dan acceso y nos sirven de señalizadores en el camino hacia la cima de la pirámide (hacia el plano del ser de DIOS).',
    'El lado oscuro del día TZ’I es la gran fuerza destructiva del desorden y la falta de un orden jurídico conectado con el corazón. Esto conduce a luchas legales, a avaricia y poder en la impartición de justicia. La desorientación de personas que viven en aberraciones como expresión de su separación anímica de DIOS, el asesinato, el derramamiento de sangre, la sexualidad desenfrenada así como los vicios en el ser humano son expresión del ser humano que vive alejado del orden divino.',
    'Las personas nacidas en el día TZ’I aman ser auténticamente su propio señor, su propia señora, orientarse únicamente en su propio sentido de la verdad, en su conducción de vida individual, en su comportamiento. Tienen un pronunciado sentido de la verdad, del orden y de las leyes de la vida; mantienen siempre conexión con sus acompañantes espirituales mediante la oración, la meditación y la comunicación diaria. Viven en sintonía consigo mismas, son leales y fiables; guardan y a la vez amplían las tradiciones, y siguen los impulsos de su cambio interior. Son excelentes abogadas, notarias, funcionarias, jueces, personas de negocios, con una conexión consciente o inconsciente con su corazón.',
    'Sus debilidades son un afán desenfrenado de poder y control, pero también una vida cotidiana desenfrenada, a menudo también una vida sexual aislada del corazón, fuertes celos y afán de posesión. Son muy engreídas, duras, egoístas y fácilmente irritables cuando son criticadas. Por su autocomplacencia se elevan gustosamente por encima de la ley y actúan con dureza de corazón, inflexibilidad y terquedad. A menudo están muy vinculadas a las tradiciones y miden a sus semejantes, condenándolos, según sus propios criterios de valor.'
  ],
  array[
    'En el día TZ’I pedimos el orden humano y divino en la comunidad. Pedimos la armonía interior mental y emocional que surge del corazón, una conducción de vida sintonizada con el orden espiritual, amplitud de miras y transparencia. Pedimos la unión sanadora de personas de distinta disposición, de estructuras empresariales, de diferentes tareas en comunidades, una convivencia armoniosa de los miembros de la familia.',
    'Pedimos reconocer y disolver estructuras endurecidas que nos obstaculizan en el camino de vida desde antiguos programas de creencia y normas de comportamiento. Pedimos la revelación de los secretos divinos que nos hacen comprensibles las conexiones más amplias de las jerarquías espirituales armonizadas entre sí. Pedimos protección frente a superiores ávidos de poder, políticos, frente a la injusticia, el acoso en el trabajo, frente a la histeria colectiva y la manipulación de masas, frente a influencias negativas por magia dañina.',
    'En TZ’I pedimos también protección para nuestra casa y nuestra familia. En procesos judiciales en curso nos conectamos, desde TZ’I, con las fuerzas espirituales protectoras, para que desde su sabiduría se encuentre una solución que resulte en bien de todos los involucrados.'
  ],
  'Hemisferio cerebral derecho, la intuición, el instinto',
  'El perro, animales protectores'
)
on conflict (nahual_index, lang) do update set
  heading = excluded.heading,
  directions = excluded.directions,
  body = excluded.body,
  ceremonies = excluded.ceremonies,
  body_level = excluded.body_level,
  power_animal = excluded.power_animal,
  updated_at = now();
